    if(s.lastError){const error=document.createElement('p');error.className='yh-launch-error';error.setAttribute('role','status');error.textContent=({'SERVER_INSTALL_FAILED':'Instalace herního serveru se nezdařila. Herní proces se nespustil, proto zatím nemá vlastní log.','NOT_ENOUGH_DISK_SPACE':'Na hostitelském počítači není dost místa.','NOT_ENOUGH_RAM':'Na hostitelském počítači není dost volné paměti.'}[s.lastError]||'Launcher akci nedokončil: '+s.lastError);host.querySelector('#yh-server-head').append(error);}
    if(['starting','stopping','syncing'].includes(s.phase)){const progress=document.createElement('div');progress.className='yh-loading yh-game-progress';progress.setAttribute('role','status');progress.innerHTML=`<span class="yh-spinner" aria-hidden="true"></span><div><strong>${({starting:'Server se spouští — ještě chvíli počkej',stopping:'Server se bezpečně ukládá a zastavuje',syncing:'Ověřujeme a přenášíme uložený svět'})[s.phase]}</strong><p>${s.phase==='starting'?(s.game!=='valheim'?'Údaje pro připojení se zobrazí po načtení světa a registraci serveru. První spuštění může trvat několik minut.':'Připojovací kód se zobrazí až po potvrzení, že je server připravený. První spuštění může trvat několik minut.'):'Nezavírej launcher. Počkej na dokončení ukládání a synchronizace.'}</p></div>`;host.querySelector('#yh-server-head').append(progress);}
    if(s.state==='host-unreachable'){
      const recovery=document.createElement('section');recovery.className='yh-recovery-notice';recovery.setAttribute('role','status');recovery.setAttribute('aria-label','Obnova po výpadku hostitele');
      recovery.innerHTML='<span class="yh-recovery-icon" aria-hidden="true">⚠</span><div><h3>Hostitel vypadl — server potřebuje obnovu</h3><p>Spojení s hostujícím počítačem se přerušilo. Bezpečné uložení z webu teď nelze potvrdit. Pro další spuštění postupuj podle pokynů níže.</p>'+(s.canResumeAfterFailure?'<p>Server už dovoluje <strong>Spustit z poslední zálohy</strong>. Vyber dostupný počítač v ovládání spuštění.</p>':s.permissions.owner?'<p><strong>Další krok: klikni na „Obnovit po výpadku hostitele“ a potvrď obnovu.</strong> Potom můžeš server znovu spustit na dostupném počítači.</p>':'<p><strong>Požádej vlastníka serveru o obnovu po výpadku hostitele.</strong> Tuto akci může potvrdit pouze vlastník.</p>')+'<p class="caption">Obnova použije poslední potvrzený stav světa. Změny, které předchozí hostitel nestihl odeslat, mohou chybět. Nejdřív ověř, že původní herní server už neběží.</p>'+(s.permissions.owner?'<button class="primary" data-yh="recover"><span aria-hidden="true">↻</span> Obnovit po výpadku hostitele</button>':'')+'</div>';
      host.querySelector('#yh-server-head').append(recovery);
    }
    const eligibleDevices=(current?.devices||[]).filter(d=>s.game==='valheim'||d.games?.includes(s.game));
