    if(op==='game-admin'){const target=await api('servers/'+id);const a=await api(`servers/${id}/game-admin`);if(target.game==='zomboid'){dialog(`<h2>Správa hry Project Zomboid</h2><p>Správcovský účet ve hře: <strong>admin</strong></p><p>Heslo správce: <strong>${esc(a.adminPassword)}</strong></p><p>Pro běžné hraní používej vlastní hráčský účet. Tyto údaje patří pouze oprávněným správcům tohoto světa.</p>`);return;}if(target.game==='palworld'){dialog(`<h2>Správa hry Palworld</h2><p>Admin heslo: <strong>${esc(a.adminPassword)}</strong></p><p>Ve hře otevři chat a zadej /AdminPassword následované tímto heslem. Potom lze použít /Save. Heslo je určené pouze oprávněným správcům tohoto světa. Svět i postavy ukládá server; bezpečné ukončení v panelu požádá Palworld o uložení a počká na vypnutí.</p>`);return;}dialog(`<h2>Správa hry The Forest</h2><p>Admin heslo: <strong>${esc(a.adminPassword)}</strong></p><p>Vlož ho do ADMIN PASSWORD při připojení. Správce může v herním chatu zadat /save pro uložení světa. Bezpečné ukončení v panelu ukládá svět automaticky.</p><p>Postavu a inventář ukládej ve hře u přístřešku. Záloha světa nenahrazuje osobní uložení hráče.</p>`);return;}
    if(op==='join'){const j=await api(`servers/${id}/join`);dialog(`<h2>Připojení do ${esc(gameName(j.game))}</h2>${j.game==='zomboid'?zomboidJoinHelp(j.config.port):j.game==='palworld'?palworldJoinHelp(j.config.port,j.connection,j.gatewayEnabled,j.password):j.game!=='valheim'?'<p>Ve hře vyhledej server: <strong>'+esc(j.name)+'</strong>. Připojení z jiné sítě se ještě ověřuje.</p>':'<p>Kód: <strong>'+esc(j.joinCode||'zatím není dostupný')+'</strong></p>'}${j.game==='palworld'?'':`<p>Heslo: <strong>${esc(j.password)}</strong></p><p>Sdílej pouze se členy své skupiny.</p>`}`);}
    if(op==='invite'){const s=await api('servers/'+id);dialog(`<h2>Pozvat člena skupiny</h2><p>Server <strong>${esc(s.name)}</strong> · ${esc(gameName(s.game))}. Práva platí jen pro tento server.</p><form id="yh-invite"><label><input type="checkbox" name="host"> Smí hostovat</label><label><input type="checkbox" name="console"> Smí číst konzoli</label>${configurationRights(s,{})}<button class="primary">Vytvořit jednorázovou pozvánku</button><p class="yh-form-error" role="status"></p></form>`);return;}
